#include <iostream>
#include <string>

int getRank(char c) {
    switch (c) {
        case 'T': return 11;
        case 'A': return 15;
        case 'K': return 14;
        case 'Q': return 13;
        case 'J': return 12;
        case '9': return 9;
        case '8': return 8;
        case '7': return 7;
        case '6': return 6;
        default: return 0;
    }
}

int main() {
    std::string ts, t, t1;
    std::cin >> ts;
    std::cin >> t >> t1;

    int x = getRank(t[0]);
    int x1 = getRank(t1[0]);

    char trump = ts[0];
    char suit1 = t[1];
    char suit2 = t1[1];

    if (suit1 == trump && suit2 != trump) {
        std::cout << "YES" << std::endl;
    } else if (suit1 != trump && suit2 == trump) {
        std::cout << "NO" << std::endl;
    } else if (suit1 != trump && suit2 != trump) {
        if (suit1 != suit2) {
            std::cout << "NO" << std::endl;
        } else {
            if (x <= x1) {
                std::cout << "NO" << std::endl;
            } else {
                std::cout << "YES" << std::endl;
            }
        }
    } else { // both trump
        if (x <= x1) {
            std::cout << "NO" << std::endl;
        } else {
            std::cout << "YES" << std::endl;
        }
    }

    return 0;
}

